  --sans:"Inter", Inter, system-ui, sans-serif;
}
html,body{font-family:var(--sans)!important}
body{background:
  radial-gradient(circle at 15% 8%,rgba(71,155,220,.13),transparent 28%),
  radial-gradient(circle at 86% 24%,rgba(74,181,196,.09),transparent 30%),
  linear-gradient(180deg,#082845 0%,#092b48 48%,#08243e 100%)!important}
h1,h2{font-family:var(--serif)!important;font-weight:600!important;letter-spacing:-.035em!important}
.hero h1{font-size:clamp(48px,6.4vw,78px)!important;line-height:.98!important}
.head h2,.problem h2,.cta h2{font-family:var(--serif)!important}
.card h3,.step h3,.mini h3,.quote b,.about-points,.q{font-family:var(--sans)!important}
.head p,.card p,.card li,.step p,.mini p,.quote p,.about-copy p,.muted{font-size:14px!important;line-height:1.7!important}
.card h3,.step h3,.mini h3{font-size:16px!important}
.card,.step,.mini,.quote{padding:25px!important}
.systems .head h2{max-width:760px;margin-left:auto;margin-right:auto}
.systems .head p{max-width:760px;margin-left:auto;margin-right:auto}
.systems .commit{font-size:15px!important;line-height:1.75!important}
.cta .box{
  background:
    radial-gradient(circle at 50% 10%,rgba(78,157,219,.16),transparent 52%),
