/* Voicework Commitment — promoted to a primary section heading */
.commitment-box{
  margin-top:28px;
  padding:32px 34px;
  border:1px solid rgba(245,201,91,.24);
  border-radius:18px;
  background:
    radial-gradient(circle at 85% 15%,rgba(245,201,91,.08),transparent 30%),
    linear-gradient(145deg,rgba(16,58,96,.72),rgba(7,35,59,.62));
  box-shadow:inset 0 1px rgba(255,255,255,.05),0 18px 55px rgba(4,20,36,.18);
}
.commitment-box h2{
  font-family:var(--serif)!important;
  font-size:clamp(42px,5vw,58px)!important;
  line-height:1.02!important;
  letter-spacing:-.04em!important;
  margin:0 0 18px!important;
}
.commitment-box p{
  margin:0 0 12px;
  max-width:900px;
  font-size:15px!important;
  line-height:1.75!important;
  color:var(--m);
}
.commitment-box .commitment-line{
  color:var(--t);
  font-weight:700;
  margin-bottom:0;
}
@media(max-width:600px){
  .commitment-box{padding:25px 20px}
  .commitment-box h2{font-size:40px!important}
}

/* Reference-matched Voicework Commitment */
.commitment-reference{
  width:min(100%, 1180px);
  margin:36px auto 0;
  padding:76px 72px 70px;
  border:1px solid rgba(229,183,72,.72);
  border-radius:30px;
  background:
    radial-gradient(circle at 48% 4%, rgba(255,255,255,.10), transparent 34%),
    radial-gradient(circle at 85% 18%, rgba(66,135,181,.13), transparent 35%),
    linear-gradient(145deg, rgba(25,68,104,.92), rgba(8,39,66,.96));
  box-shadow:0 30px 90px rgba(4,20,36,.22), inset 0 1px rgba(255,255,255,.06);
  text-align:center;
}
.commitment-reference .commitment-eyebrow{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  padding:11px 26px;
  border:1px solid rgba(235,190,74,.58);
  border-radius:999px;
  background:rgba(230,184,69,.08);
  color:#f0c65d;
  font:700 14px/1 var(--sans);
  letter-spacing:.15em;
  margin-bottom:50px;
}
.commitment-reference h2{
  margin:0 auto 46px!important;
  color:#fbf7ed;
  font-family:var(--serif)!important;
  font-size:clamp(48px,6.2vw,76px)!important;
  line-height:1.03!important;
  letter-spacing:-.045em!important;
  max-width:1000px;
}
.commitment-reference > p{
  margin:0 auto;
  max-width:1040px;
  color:#d7e1eb;
  font:500 clamp(18px,2vw,23px)/1.65 var(--sans)!important;
}
.commitment-reference .commitment-divider{
  height:1px;
  width:88%;
  margin:48px auto 38px;
  background:rgba(255,255,255,.16);
}
.commitment-reference .commitment-line{
  margin:0 auto!important;
  color:#f4c85b!important;
  font:600 italic clamp(22px,2.6vw,32px)/1.35 var(--serif)!important;
}

/* Global responsive polish */
img,video,iframe{max-width:100%;height:auto}
body{overflow-x:hidden}
.container,.wrap,.section-inner{width:min(100% - 40px, 1180px);margin-inline:auto}
@media (max-width: 900px){
  .container,.wrap,.section-inner{width:min(100% - 32px, 760px)}
  .commitment-reference{padding:58px 42px 54px;border-radius:24px}
  .commitment-reference .commitment-eyebrow{margin-bottom:36px}
  .commitment-reference h2{margin-bottom:32px!important}
  .commitment-reference .commitment-divider{margin:38px auto 28px}
}
@media (max-width: 640px){
  .container,.wrap,.section-inner{width:calc(100% - 28px)}
  .commitment-reference{
    padding:42px 20px 40px;
    border-radius:20px;
    margin-top:24px;
  }
  .commitment-reference .commitment-eyebrow{
    padding:9px 15px;
    font-size:10px;
    letter-spacing:.13em;
    margin-bottom:27px;
  }
  .commitment-reference h2{
    font-size:clamp(37px,11vw,48px)!important;
    line-height:1.05!important;
    margin-bottom:26px!important;
  }
  .commitment-reference > p{
    font-size:16px!important;
    line-height:1.65!important;
  }
  .commitment-reference .commitment-divider{
    width:100%;
    margin:30px auto 25px;
  }
  .commitment-reference .commitment-line{
    font-size:21px!important;
    line-height:1.38!important;
  }

  /* Mobile typography/readability */
  h1{font-size:clamp(40px,12vw,58px)!important}
  h2{font-size:clamp(34px,10vw,48px)!important}
  p{max-width:100%}
  .card,.step,.mini,.quote{padding:20px!important}
  .head p,.card p,.card li,.step p,.mini p,.quote p,.about-copy p{font-size:14px!important}

  /* Prevent marquee/cards from forcing horizontal scrolling */
  .marquee,.video-marquee,.track{max-width:100%;overflow:hidden}
  .video-card{flex:0 0 min(78vw,300px)}

  /* Stack common two/three-column grids */
  .grid-3,.cards-3{grid-template-columns:1fr!important}
  .grid-2,.cards-2{grid-template-columns:1fr!important}
}

