/* =========================================================
   Voicework — FINAL TYPE + MOTION SYSTEM
   Structural type: Inter
   Commentary type: Caveat
   ========================================================= */
:root{
  --vw-font:"Inter",system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
  --vw-script:"Caveat",cursive;
  --vw-gold:#f2c65b;
  --vw-gold-soft:#ffd978;
  --vw-text:#f5f7fb;
  --vw-muted:#aebdcb;
  --vw-panel:#0d2945;
  --vw-panel-2:#102f4d;
  --vw-line:rgba(155,195,225,.18);
}

/* One structural font everywhere. */
html,body,button,input,textarea,select{
  font-family:var(--vw-font)!important;
}
h1,h2,h3,h4,h5,h6,
.logo,.btn,.links a,.ey,.top,.stage,.stage strong,
.trust-title,.trust-logo,.commitment-eyebrow,.q,
.engine-name,.engine-kicker,.engine-intro,.engine-status,
.process .num,.before .label,.after .label{
  font-family:var(--vw-font)!important;
}

/* No serif/display-face anywhere. */
[class*="serif"],.serif{
  font-family:var(--vw-font)!important;
}

/* Structural heading hierarchy. */
h1,h2,h3,h4,h5,h6{
  font-weight:700!important;
  letter-spacing:-.025em!important;
}
.hero h1{
  font-family:var(--vw-font)!important;
  font-weight:800!important;
}
.head h2,.problem h2,.about-copy h2,.cta h2{
  font-family:var(--vw-font)!important;
  font-weight:750!important;
}

/* Gold commentary = human voice. Thin, elegant, consistent. */
.detail-copy,
.commitment-line,
.video-watch{
  font-family:var(--vw-script)!important;
  font-weight:500!important;
  letter-spacing:.01em!important;
  color:var(--vw-gold-soft)!important;
}
.detail-copy{
  font-size:28px!important;
  line-height:1.05!important;
}
.commitment-line{
  font-size:24px!important;
  line-height:1.15!important;
}
.video-watch{
  font-size:19px!important;
  line-height:1!important;
}

/* ---------------------------------------------------------
   Voicework ENGINE
   --------------------------------------------------------- */
.engine-brand{
  align-items:center!important;
  gap:22px!important;
}
.engine-name{
  font-family:var(--vw-font)!important;
  font-weight:800!important;
  letter-spacing:-.045em!important;
  line-height:.92!important;
}
.engine-name span,
.engine-name em{
  display:block!important;
  font-family:var(--vw-font)!important;
  font-style:normal!important;
  font-weight:800!important;
}
.engine-name span{
  color:#f1f6fb!important;
  font-size:31px!important;
}
.engine-name em{
  color:var(--vw-gold)!important;
  font-size:38px!important;
  margin-top:5px!important;
}

/* Identical physical treatment for all five stages. */
.grid5{
  gap:24px!important;
  align-items:stretch!important;
}
.stage,
.stage.active,
.stage:hover{
  position:relative!important;
  transform:none!important;
  top:auto!important;
  background:linear-gradient(145deg,rgba(24,60,90,.72),rgba(12,36,60,.86))!important;
  border:1px solid rgba(126,164,194,.20)!important;
  border-radius:18px!important;
  box-shadow:none!important;
  min-height:194px!important;
  padding:20px 14px 18px!important;
  transition:border-color .3s ease,box-shadow .3s ease,background .3s ease!important;
}
.stage:hover{
  border-color:rgba(242,198,91,.42)!important;
  box-shadow:0 0 28px rgba(64,164,220,.10)!important;
  background:linear-gradient(145deg,rgba(27,66,98,.78),rgba(13,39,65,.90))!important;
}

/* Remove the old “Step 1 is elevated” feeling. */
.stage.active{
  border-color:rgba(126,164,194,.20)!important;
  box-shadow:none!important;
}

/* Engine's new motion language: a production pulse, not lightning. */
.stage{
  animation:vwEnginePulse 8s ease-in-out infinite!important;
}
.stage:nth-child(1){animation-delay:0s!important}
.stage:nth-child(2){animation-delay:1.6s!important}
.stage:nth-child(3){animation-delay:3.2s!important}
.stage:nth-child(4){animation-delay:4.8s!important}
.stage:nth-child(5){animation-delay:6.4s!important}

@keyframes vwEnginePulse{
  0%,16%,100%{
    border-color:rgba(126,164,194,.20);
    box-shadow:0 0 0 rgba(65,190,255,0);
  }
  8%{
    border-color:rgba(89,199,255,.78);
    box-shadow:0 0 26px rgba(65,190,255,.16), inset 0 0 22px rgba(65,190,255,.04);
  }
  13%{
    border-color:rgba(242,198,91,.40);
    box-shadow:0 0 12px rgba(65,190,255,.08);
  }
}

/* Connecting production line + small directional chevron. */
.grid5 .stage:not(:last-child)::after{
  content:"";
  position:absolute;
  z-index:3;
  top:50%;
  right:-24px;
  width:24px;
  height:1px;
  background:linear-gradient(90deg,rgba(77,183,244,.18),rgba(112,211,255,.85));
  transform:translateY(-50%);
  pointer-events:none;
}
.grid5 .stage:not(:last-child)::before{
  content:"";
  position:absolute;
  z-index:4;
  top:50%;
  right:-24px;
  width:7px;
  height:7px;
  border-top:2px solid #8bdcff;
  border-right:2px solid #8bdcff;
  transform:translate(0,-50%) rotate(45deg);
  filter:drop-shadow(0 0 5px rgba(91,205,255,.55));
  pointer-events:none;
}
.grid5 .stage:not(:last-child)::after{
  animation:vwFlowLine 8s ease-in-out infinite;
}
.grid5 .stage:nth-child(1)::after{animation-delay:0s}
.grid5 .stage:nth-child(2)::after{animation-delay:1.6s}
.grid5 .stage:nth-child(3)::after{animation-delay:3.2s}
.grid5 .stage:nth-child(4)::after{animation-delay:4.8s}

@keyframes vwFlowLine{
  0%,16%,100%{opacity:.32;box-shadow:none}
  8%{opacity:1;box-shadow:0 0 13px rgba(86,202,255,.85)}
  13%{opacity:.48;box-shadow:0 0 5px rgba(86,202,255,.35)}
}

.stage-icon{
  transition:transform .35s ease,filter .35s ease!important;
}
.stage:nth-child(1) .stage-icon{color:#7fcfff!important}
.stage:nth-child(2) .stage-icon{color:#d084ff!important}
.stage:nth-child(3) .stage-icon{color:#f2c65b!important}
.stage:nth-child(4) .stage-icon{color:#65dfae!important}
.stage:nth-child(5) .stage-icon{color:#ff76a4!important}

.stage strong{
  font-family:var(--vw-font)!important;
  font-size:16px!important;
  font-weight:700!important;
  letter-spacing:-.015em!important;
}
.stage small{
  font-family:var(--vw-font)!important;
  font-size:11px!important;
  font-weight:500!important;
}

/* Engine footer statement: wider, airy, script. */
.flow .detail{
  margin-top:24px!important;
  gap:28px!important;
}
.flow .detail-line{
  flex:1 1 120px!important;
  max-width:120px!important;
  opacity:.55!important;
}
.flow .detail-copy{
  white-space:nowrap!important;
}

/* Larger brand statements elsewhere. */
.commitment-box.commitment-reference h2{
  font-family:var(--vw-font)!important;
  font-weight:750!important;
  font-size:clamp(34px,4.4vw,54px)!important;
  line-height:1.04!important;
}
.commitment-box.commitment-reference p{
  font-family:var(--vw-font)!important;
}

/* CTA statement should not look like FAQ copy. */
.cta .box h2{
  font-family:var(--vw-font)!important;
  font-weight:750!important;
  font-size:clamp(34px,4.5vw,56px)!important;
  line-height:1.02!important;
  letter-spacing:-.035em!important;
}
.cta .box p{
  max-width:720px!important;
}

/* Keep FAQ intentionally quieter/smaller. */
#faq .q{
  font-family:var(--vw-font)!important;
  font-size:15px!important;
  font-weight:650!important;
}
#faq .ans{
  font-family:var(--vw-font)!important;
}

/* “Click any episode to watch” = same commentary language. */
.video-watch{
  color:var(--vw-gold-soft)!important;
}

/* Buttons/navigation remain Inter. */
.btn,.links a,.logo{
  font-family:var(--vw-font)!important;
  font-weight:600!important;
}

/* Reduce the old cursor/ambient effects around the Engine. */
.flow,
.flow .box{
  overflow:hidden!important;
}
.flow .box::before,
.flow .box::after{
  pointer-events:none!important;
}

/* Mobile: remove inter-card connectors rather than letting them collide. */
@media(max-width:900px){
  .grid5{
    grid-template-columns:1fr!important;
    gap:14px!important;
  }
  .grid5 .stage:not(:last-child)::before,
  .grid5 .stage:not(:last-child)::after{
    display:none!important;
  }
  .stage,.stage.active,.stage:hover{
    min-height:170px!important;
  }
  .flow .detail-copy{
    white-space:normal!important;
    text-align:center!important;
  }
  .flow .detail{
    gap:12px!important;
  }
}
@media(prefers-reduced-motion:reduce){
  .stage,.grid5 .stage:not(:last-child)::after{
    animation:none!important;
  }
}

